"""DataSourceRegistry — instantiates providers and builds datasource metadata from config."""

from __future__ import annotations

from project_health.config.loader import Config
from project_health.providers.protocol import Datasource, DataSourceProvider, DatasourceRole


class DataSourceRegistry:
    """Holds active data source providers and datasource metadata keyed by source id."""

    def __init__(
        self,
        providers: list[DataSourceProvider],
        datasources: list[Datasource],
    ) -> None:
        self._providers: dict[str, DataSourceProvider] = {p.id: p for p in providers}
        self._datasources: list[Datasource] = datasources

    def get(self, source_id: str) -> DataSourceProvider | None:

import { useState, useCallback, useRef, useEffect } from 'react'
import { useSearchParams } from 'react-router-dom'
import { useProjects } from '../hooks/useMetrics'

type DatasourceGroup = {
  id: string
  role: string
  display_name: string
  projects: string[]
}

export default function DatasourceProjectFilter() {
  const [searchParams, setSearchParams] = useSearchParams()
  const { data, isLoading } = useProjects()
  const [open, setOpen] = useState(false)
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({})
  const ref = useRef<HTMLDivElement>(null)

  const datasource = searchParams.get('datasource') ?? ''
  const project = searchParams.get('project') ?? ''

import { useState } from 'react'
import type { components } from '../api/types'

type WorkItem = components['schemas']['WorkItem']

interface WorkItemCardProps {
  item: WorkItem
  compact?: boolean
}

function DatasourceBadge({ datasource }: { datasource: string }) {
  if (datasource === 'jira') {
    return <span className="inline-block px-1.5 py-0.5 rounded text-xs font-medium bg-purple-100 text-purple-700">Jira</span>
  }
  if (datasource === 'launchpad') {
    return <span className="inline-block px-1.5 py-0.5 rounded text-xs font-medium bg-orange-100 text-orange-700">LP</span>
  }
  return <span className="inline-block px-1.5 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-600">GH</span>
}

