 def parse_launchpad_repo_path(path: str) -> tuple[str, str, str]:
     """Parse a canonical Launchpad Git repo path into owner, context, repository."""
     match = re.fullmatch(r"(?P<owner>~[^/]+)/(?P<context>[^/]+)/\+git/(?P<repo>[^/]+)", path)
     if match is None:
         raise ValueError(
